import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"ADR-0078: Owner-approved release signing","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0078-owner-approved-release-signing.md","filePath":"adrs/0078-owner-approved-release-signing.md","lastUpdated":1789092097000}`),a={name:`adrs/0078-owner-approved-release-signing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0078-owner-approved-release-signing" tabindex="-1">ADR-0078: Owner-approved release signing <a class="header-anchor" href="#adr-0078-owner-approved-release-signing" aria-label="Permalink to “ADR-0078: Owner-approved release signing”">​</a></h1><p>Status: Accepted · Refines <a href="/adrs/0007-no-app-sandbox">ADR-0007</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Ad-hoc signing allows contributors to build GOAT without Apple membership, but macOS cannot reliably preserve local-network permission across changed ad-hoc identities. Official downloads need a verified publisher, hardened runtime and notarization. The release owner must approve use of their signing key.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Keep ad-hoc signing as the shared project default. Maintainers may select a certificate and team in an ignored <code>signing.local.mk</code>; make forwards those settings to Xcode. No private key or personal signing identity is committed.</p><p>Separate CI verification from the signing job. Release automation is disabled unless explicitly enabled for the configured owner in the official repository. Signing requires the <code>release-signing</code> environment, configured with that owner&#39;s approval and release-tag restrictions. The same owner may initiate and approve a run. Signing credentials belong only to that environment. Forks and pull requests have no official signing path.</p><p>Check all required signing secrets before certificate import. Verify the resulting app and CLI signatures against an Apple trust anchor, the expected Developer ID Application publisher and team, hardened runtime and a secure timestamp. Official releases must complete notarization and stapling; missing credentials or a rejected submission fail the workflow. Publication remains manual from a draft release.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Contributor builds remain available without paid Apple membership. Local acceptance builds can use a stable certificate while official signing remains disabled. GitHub environment protection must be configured outside YAML; private repositories without required-reviewer support must keep the release key local. A repository visibility change, credential export or publication is a separate owner action.</p><p>Configuration and signature regressions check missing credentials, wrong teams, non-Developer-ID certificates, malformed certificate encoding, absent hardened runtime and accidental notarization skipping. This does not replace live notarization and clean-machine Gatekeeper acceptance.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};